solution:
def can_split(nums: list[int]) -> bool:
    total = sum(nums)
    if total % 2:
        return False                     # an odd total never halves
    half = total // 2
    reach = [True] + [False] * half      # reach[s]: some group of the numbers so far sums to s
    for x in nums:
        for s in range(half, x - 1, -1): # downward, so x is used at most once
            if reach[s - x]:
                reach[s] = True
    return reach[half]

