perf.naive:
def can_split(nums: list[int]) -> bool:
    total = sum(nums)
    if total % 2:
        return False
    def pick(i, left):                   # can some of nums[i:] add up to `left`? re-explored on every call
        if left == 0:
            return True
        if i == len(nums) or left < 0:
            return False
        return pick(i + 1, left - nums[i]) or pick(i + 1, left)
    return pick(0, total // 2)
